BlockingQueue<Job> q = new LinkedBlockingQueue<>(100);
new Thread(() -> {
    while (true) {
        try { handle(q.take()); }              // exactly one consumer gets it
        catch (InterruptedException e) { Thread.currentThread().interrupt(); return; }
    }
}).start();
